#!/usr/bin/env python3
"""Collect Friend-Message commits from all friend/* branches and compare with main transcripts."""
import subprocess, re, os, json, sys
from collections import defaultdict

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args):
    return subprocess.run(["git", "-C", REPO] + list(args), capture_output=True, text=True, check=True).stdout


def collect():
    msgs = []
    for b in BRANCHES:
        branch = "origin/friend/%s" % b
        out = git("log", "--format=%H%x00%cI%x00%ct", branch)
        for line in out.splitlines():
            if not line.strip():
                continue
            sha, ciso, ct = line.split("\0")
            body = git("show", "-s", "--format=%B", sha)
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            ep = re.search(r"^Episode:\s*(\S+)\s*$", body, re.M)
            sp = re.search(r"^Speaker:\s*(.+?)\s*$", body, re.M)
            rt = re.search(r"^Reply-To:\s*(\S*)\s*$", body, re.M)
            # utterance = text after the blank line following Reply-To block
            m = re.search(r"^(?:Reply-To:.*\n(?:Correction-Request:.*\n)?)\n", body, re.M)
            if m:
                utt = body[m.end():]
            else:
                utt = body
            utt = utt.strip("\n")
            msgs.append(dict(sha=sha, branch="friend/%s" % b, episode=ep.group(1) if ep else "S01/E01",
                             speaker=sp.group(1) if sp else b.capitalize(),
                             reply_to=rt.group(1) if rt else "", ct=int(ct), ciso=ciso, text=utt))
    return msgs


def existing_sources(main_dir):
    found = {}
    for root, dirs, files in os.walk(main_dir):
        for f in files:
            if re.match(r"^E\d+\.md$", f):
                p = os.path.join(root, f)
                txt = open(p).read()
                ep = "S%02d/%s" % (int(os.path.basename(root)[1:]), f)
                for m in re.finditer(r"^Source: (\S+) @ ([0-9a-f]{40})\s*$", txt, re.M):
                    found.setdefault(m.group(2), []).append(ep)
    return found


if __name__ == "__main__":
    msgs = collect()
    existing = existing_sources(sys.argv[1] if len(sys.argv) > 1 else "/tmp/fw/main")
    by_ep = defaultdict(list)
    for m in msgs:
        by_ep[m["episode"]].append(m)
    missing_total = 0
    for ep in sorted(by_ep, key=lambda e: (e.split("/")[0], int(e.split("/E")[1]))):
        lst = sorted(by_ep[ep], key=lambda m: (m["ct"], m["sha"]))
        miss = [m for m in lst if m["sha"] not in existing]
        missing_total += len(miss)
        if miss or "-v" in sys.argv:
            print("%s total=%d transcribed=%d missing=%d" % (ep, len(lst), len(lst) - len(miss), len(miss)))
            for m in miss:
                print("   MISSING %s %s %s reply=%s :: %s" % (m["sha"][:9], m["branch"], m["speaker"], m["reply_to"][:9], m["text"][:90].replace("\n", " ")))
    print("TOTAL messages=%d missing=%d" % (len(msgs), missing_total))
    # also find transcript files whose source shas no longer exist in branches
    for sha, eps in existing.items():
        if sha not in {m["sha"] for m in msgs}:
            print("ORPHAN in transcript:", sha[:9], eps)
